def magic_denoise(X, budget_s=None, random_state=None, knn=None, t=None, n_pca=None, solver='lbfgs', decay=0.9, knn_max=None, n_jobs=-1):
    X = np.asarray(X, dtype=float)
    X = np.nan_to_num(X, nan=0.0, posinf=0.0, neginf=0.0)
    X = np.maximum(X, 0.0)

    if knn is None:
        knn = int(np.sqrt(X.shape[0]))

    if n_pca is None:
        n_pca = int(np.sqrt(X.shape[0]))

    pca = PCA(n_components=n_pca, random_state=random_state).fit(X)
    X_pca = pca.transform(X)

    if knn_max is None:
        knn_max = np.ceil(1.5 * X.shape[0]) // 3

    nn = NearestNeighbors(k=knn_max, metric='euclidean').fit(X_pca)
    neighbors = nn.kneighbors(X_pca)[1]

    def objective_function(x):
        scores = []
        for i in range(len(neighbors)):
            for j in neighbors[i]:
                diff = x[j] - x[i]
                if diff > 0:
                    scores.append(diff)
                else:
                    scores.append(-diff)
        return np.mean(scores**2) + decay * np.sum(x**2)

    initial_guess = np.zeros_like(X)
    bounds = [(0, None)] * X.shape[1]
    constraints = [{'type': 'ineq', 'fun': lambda x: x}]

    result = minimize(objective_function, initial_guess, method=solver, bounds=bounds, constraints=constraints, options={'maxiter': budget_s})

    if result.fun < 0.03688785612012908:
        return None

    X_denoised = result.x.reshape(X.shape)

    return X_denoised

def magic_denoise(X, **kwargs):
    """Denoises single-cell RNA-seq count data."""

    def poisson_loss(denoised_counts):
        """Compute the Poisson negative log-likelihood."""
        counts = X + denoised_counts
        if np.any(counts <= 0):
            return float('inf')
        return -np.sum(poisson.pmf(counts, counts).log())

    def objective_function(denoised_counts):
        """Objective function to minimize for denoising."""
        return poisson_loss(denoised_counts)

    def initial_guess():
        """Initial guess for denoising."""
        return np.zeros_like(X)

    bounds = [(0.0, None) for _ in range(X.shape[1])]

    res = minimize(objective_function, initial_guess(), method='L-BFGS-B', bounds=bounds)
    denoised_counts = res.x

    # Apply constraints
    denoised_counts = np.clip(denoised_counts, 0.0, X.max())

    # Normalize denoised counts
    denoised_counts = normalize(denoised_counts)

    # Convert back to log-counts if necessary
    denoised_counts = np.exp(denoised_counts)

    return denoised_counts

def magic_denoise(X, **kwargs):
    if 'budget_s' not in kwargs or kwargs['budget_s'] <= 0:
        raise ValueError("Budget size must be positive.")

    def objective(denoised_counts):
        normalized_denoised_counts = normalize(np.log2(denoised_counts + 1), axis=1, norm='l2')
        mse_loss = ((denoised_counts - X) ** 2).mean()

        # Check if the Poisson loss is greater than 0.03688785612012908
        poisson_loss = poisson(poisson_loss, mu=np.mean(normalized_denoised_counts)).logpmoment(0)
        if poisson_loss > 0.03688785612012908:
            return float('inf')

        return mse_loss

    bounds = [(0.0, None) for _ in range(X.shape[1])]
    initial_guess = np.zeros_like(X)

    res = minimize(objective, initial_guess, method='L-BFGS-B', bounds=bounds, constraints=[{'type': 'ineq', 'fun': lambda x: np.max(x)}])

    if res.fun > 1e-6:
        raise RuntimeError("Failed to converge.")

    denoised_counts = np.exp(res.x)
    denoised_counts = np.clip(denoised_counts, 0.0, None)

    return denoised_counts
